//! Module containing sample struct types generated by the
//! [`i2cs!`](macro@crate::i2cs) macro: [`I2csGenerated`], with the displays
//! [`LcdTextGenerated`] and [`LcdTextGenerated20x4`].
//!
//! Every item on the sample pages is the macro's own output for the declaration in this
//! file, so the pages show exactly what a declaration generates.

#[cfg(all(not(feature = "host"), target_os = "none"))]
use crate::i2cs;

#[cfg(all(not(feature = "host"), target_os = "none"))]
i2cs! {
    pub I2csGenerated {
        sda_pin: GPIO4,
        scl_pin: GPIO5,
        i2c: I2C0,

        LcdTextGenerated { width: 16, height: 2, address: 0x27 },
        LcdTextGenerated20x4 { width: 20, height: 4, address: 0x3F },
    }
}
